constructor(
        address vat_,
        address pot_,
        address treasury_,
        uint256 maturity_,
        string memory name,
        string memory symbol
    ) public ERC20(name, symbol) {
        _vat = IVat(vat_);
        _pot = IPot(pot_);
        _treasury = ITreasury(treasury_);
        maturity = maturity_;
        chi0 = UNIT;
        rate0 = UNIT;
    }

function chiGrowth() public view override returns(uint256){
        if (isMature != true) return chi0;
        return Math.min(rateGrowth(), divd(_pot.chi(), chi0)); // Rounding in favour of the protocol
    }

function rateGrowth() public view override returns(uint256){
        if (isMature != true) return rate0;
        (, uint256 rate,,,) = _vat.ilks(WETH);
        return Math.max(UNIT, divdrup(rate, rate0)); // Rounding in favour of the protocol
    }

function muld(uint256 x, uint256 y) internal pure returns (uint256) {
        return x.mul(y).div(UNIT);
    }

function divd(uint256 x, uint256 y) internal pure returns (uint256) {
        return x.mul(UNIT).div(y);
    }

function divdrup(uint256 x, uint256 y)
        internal pure returns (uint256)
    {
        uint256 z = x.mul(10000000000000000000000000000).div(y); // RAY * 10
        if (z % 10 > 0) return z / 10 + 1;
        else return z / 10;
    }

modifier onlyHolderOrDelegate(address holder, string memory errorMessage) {
        require(
            msg.sender == holder || delegated[holder][msg.sender],
            errorMessage
        );
        _;
    }

function addDelegate(address delegate) public {
        delegated[msg.sender][delegate] = true;
        emit Delegate(msg.sender, delegate, true);
    }

function revokeDelegate(address delegate) public {
        delegated[msg.sender][delegate] = false;
        emit Delegate(msg.sender, delegate, false);
    }

function permit(address owner, address spender, uint256 amount, uint256 deadline, uint8 v, bytes32 r, bytes32 s) public virtual override {
        require(deadline >= block.timestamp, "ERC20Permit: expired deadline");

        bytes32 hashStruct = keccak256(
            abi.encode(
                PERMIT_TYPEHASH,
                owner,
                spender,
                amount,
                nonces[owner]++,
                deadline
            )
        );

        bytes32 hash = keccak256(
            abi.encodePacked(
                '\x19\x01',
                DOMAIN_SEPARATOR,
                hashStruct
            )
        );

        address signer = ecrecover(hash, v, r, s);
        require(
            signer != address(0) && signer == owner,
            "ERC20Permit: invalid signature"
        );

        _approve(owner, spender, amount);
    }

modifier onlyOrchestrated(string memory err) {
        require(authorized[msg.sender], err);
        _;
    }

function orchestrate(address user) public onlyOwner {
        authorized[user] = true;
        emit GrantedAccess(user);
    }

